// ─── IMAGE THUMBS ────────────────────────────────────────────────────────────
// Downsized WebP copies generated by scripts/make-thumbs.mjs into
// window.IMAGE_THUMBS (assets/image-thumbs.js). An image with no entry yet
// (added to the data but the script not re-run) falls back to the original.
const IMAGE_THUMBS = window.IMAGE_THUMBS || {};

function thumbOf(src) {
  const t = IMAGE_THUMBS[src];
  return t ? { src: t[0], width: t[1], height: t[2] } : { src };
}

// onError handler: if a thumb is missing from the deploy, swap in the
// original once instead of leaving the image stuck behind its spinner.
function fallbackToOriginal(original) {
  return (e) => {
    const img = e.currentTarget;
    if (img.dataset.fellBack) return;
    img.dataset.fellBack = '1';
    img.src = original;
  };
}
